const here = position();
if (inventory_count('wheat_seeds') < 1) {
  const grass = find_block({ names: ['tall_grass', 'grass'], max_distance: 16 });
  if (!grass) {
    return { done: false, detail: 'no tall grass to gather seeds from' };
  }
  await dig(grass.x, grass.y, grass.z);
}
if (inventory_count('wheat_seeds') < 1) {
  return { done: false, detail: 'no seeds to plant' };
}
await place('wheat_seeds', here.x + 1, here.y, here.z);
return { done: true, detail: 'planted seeds' };
